parameters.jsCode:
const items = $input.all();
const expected = ['aspect_sentiment_analysis', 'abstraction_analysis', 'plot_description', ''];
if (items.length !== expected.length) throw new Error(`Expected 4 results, received ${items.length}`);
return items.map((item, i) => {
  const r = item.json.output;
  if (!r || r.case.feature_key !== expected[i]) throw new Error(`Incorrect feature for report ${i + 1}`);
  if (r.ready_for_investigation !== false) throw new Error('Premature investigation readiness');
  if (!r.reply_text || r.questions.length > 3 || r.questions.length === 0) throw new Error('Missing or excessive follow-up questions');
  if (r.status !== (i === 3 ? 'UNKNOWN_FEATURE' : 'NEED_MORE_INFO')) throw new Error(`Incorrect status for report ${i + 1}`);
  if (i === 0 && (r.case.request_state !== 'not_created' || r.missing_fields.includes('request_id'))) throw new Error('Pre-creation request_id incorrectly required');
  return {json: {test: i + 1, status: r.status, feature_key: r.case.feature_key, questions: r.questions, passed: true}};
});
